<script setup lang="ts">
import EmployeeSearchSelect from '../../Components/EmployeeSearchSelect.vue';
import EmployeeMultiSearchSelect from '../../Components/EmployeeMultiSearchSelect.vue';
import { Head, useForm } from '@inertiajs/vue3';
import AdminLayout from '../../../../../CORE/Resources/js/Layouts/AdminLayout.vue';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
const p=defineProps<{employeeOptions:any[]}>();
const f=useForm({scope:'single',employee_id:'',employee_ids:[] as string[],increment_type:'percentage',increment_value:0,effective_date:new Date().toISOString().slice(0,10),reason:''});
function submit(){if(f.scope==='all'&&!window.confirm('Create a pending salary increment for every payroll-eligible employee (Active or On Leave)?'))return;if(f.scope==='selected'&&!f.employee_ids.length){window.alert('Select at least one employee.');return}f.post(route('payroll.increments.store'))}
</script>
<template><AdminLayout :breadcrumbs="[{title:'PAYROLL'},{title:'Increments',href:route('payroll.increments.index')},{title:'Request'}]"><Head title="Request increment"/><div class="mx-auto max-w-3xl rounded-xl border bg-card p-6"><h1 class="text-xl font-bold">Request salary increment</h1><p class="mt-1 text-sm text-muted-foreground">Submit an approval request for one employee, selected employees, or all payroll-eligible employees. Percentage changes apply to each employee's salary effective on the selected date.</p><form @submit.prevent="submit" class="mt-5 space-y-4"><div class="space-y-2"><Label>Employees</Label><select v-model="f.scope" class="h-10 w-full rounded-md border bg-background px-3"><option value="single">One employee</option><option value="selected">Selected employees</option><option value="all">All active employees</option></select></div><div v-if="f.scope==='single'" class="space-y-2"><Label>Employee</Label><EmployeeSearchSelect v-model="f.employee_id" :options="employeeOptions"/><p v-if="f.errors.employee_id" class="text-xs text-destructive">{{f.errors.employee_id}}</p></div><div v-if="f.scope==='selected'" class="space-y-2"><Label>Choose employees</Label><EmployeeMultiSearchSelect v-model="f.employee_ids" :options="employeeOptions"/><p v-if="f.errors.employee_ids" class="text-xs text-destructive">{{f.errors.employee_ids}}</p></div><div v-if="f.scope==='all'" class="rounded-lg bg-amber-500/10 p-3 text-sm">This creates individual pending approval records for all active employees. The increment is not applied until each record is approved.</div><div class="grid grid-cols-2 gap-4"><div class="space-y-2"><Label>Increase method</Label><select v-model="f.increment_type" class="h-10 w-full rounded-md border bg-background px-3"><option value="percentage">Percentage</option><option value="fixed">Fixed amount</option></select></div><div class="space-y-2"><Label>{{f.increment_type==='percentage'?'Increase percent':'Increase amount'}}</Label><Input v-model.number="f.increment_value" type="number" min="0.01" step="0.01"/><p v-if="f.errors.increment_value" class="text-xs text-destructive">{{f.errors.increment_value}}</p></div></div><div class="space-y-2"><Label>Effective date</Label><Input v-model="f.effective_date" type="date"/><p v-if="f.errors.effective_date" class="text-xs text-destructive">{{f.errors.effective_date}}</p></div><div class="space-y-2"><Label>Reason (required for audit)</Label><textarea v-model="f.reason" class="min-h-24 w-full rounded-md border bg-background p-3"/><p v-if="f.errors.reason" class="text-xs text-destructive">{{f.errors.reason}}</p></div><Button :disabled="f.processing">Submit for approval</Button></form></div></AdminLayout></template>
